function fractionToText(num: number, den: number): string {
  if (num === 0) return "0";
  const out: string[] = [];
  if ((num < 0) !== (den < 0)) out.push("-");
  const n = Math.abs(num), d = Math.abs(den);
  out.push(String(Math.floor(n / d)));
  let rem = n % d;
  if (rem === 0) return out.join("");
  out.push(".");
  const seenAt = new Map<number, number>();
  while (rem !== 0) {
    if (seenAt.has(rem)) {
      out.splice(seenAt.get(rem)!, 0, "(");
      out.push(")");
      break;
    }
    seenAt.set(rem, out.length);
    rem *= 10;
    out.push(String(Math.floor(rem / d)));
    rem %= d;
  }
  return out.join("");
}

