function fractionToText(num: number, den: number): string {
  if (num === 0) return "0";
  const sign = (num < 0) !== (den < 0) ? "-" : "";
  let n = Math.abs(num), d = Math.abs(den);
  const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));
  const g = gcd(n, d);
  n /= g; d /= g;
  const whole = sign + String(Math.floor(n / d));
  let rem = n % d;
  if (rem === 0) return whole;
  // pre-period length = max(exponent of 2, exponent of 5) in d
  let twos = 0, fives = 0;
  for (let x = d; x % 2 === 0; x /= 2) twos++;
  for (let x = d; x % 5 === 0; x /= 5) fives++;
  const pre = Math.max(twos, fives);
  let head = "";
  for (let i = 0; i < pre; i++) {
    rem *= 10;
    head += Math.floor(rem / d);
    rem %= d;
  }
  if (rem === 0) return whole + "." + head;
  const start = rem;
  let cycle = "";
  do {
    rem *= 10;
    cycle += Math.floor(rem / d);
    rem %= d;
  } while (rem !== start);
  return whole + "." + head + "(" + cycle + ")";
}

